SELECT k.name || ' — есть состояние (' || h.t || '), а переоткрывается вид или нет, не объявлено' AS detail FROM kind_layout k CROSS JOIN LATERAL jsonb_array_elements_text(coalesce(k.spec->'holds','[]'::jsonb)) h(t) JOIN information_schema.columns c ON c.table_schema = 'public' AND c.table_name = h.t AND c.column_name IN ('state','status','closed','satisfied') WHERE NOT (k.spec ? 'reopens') AND coalesce(k.spec->>'projection','') <> 'container' AND EXISTS (SELECT 1 FROM project_documents d WHERE d.project_id = $1 AND d.entity_kind = k.name) GROUP BY k.name, h.t ORDER BY 1
